def find_golomb(n=8, fixed={}):
    marks = [0] * n
    marks[0] = 0
    seen = set()
    start_pos = 1
    if 1 in fixed:
        marks[1] = fixed[1]
        seen.add(marks[1] - marks[0])
        start_pos = 2
    def backtrack(pos, max_val):
        if pos == n:
            return True
        start = marks[pos-1] + 1
        for val in range(start, max_val + 1):
            can_place = True
            new_diffs = []
            for i in range(pos):
                diff = val - marks[i]
                if diff in seen:
                    can_place = False
                    break
                new_diffs.append(diff)
            if can_place:
                marks[pos] = val
                for d in new_diffs:
                    seen.add(d)
                if backtrack(pos + 1, max_val):
                    return True
                for d in new_diffs:
                    seen.remove(d)
        return False
    # Try with increasing max_val until found
    for length in range(10, 200):
        if backtrack(start_pos, length):
            return marks, length
    return None, None

result = find_golomb(fixed={1:2})
print(result)
